/**
 * Pure helpers for surfacing the Agent's soul file in the context panel.
 *
 * The soul file is a markdown document generated by
 * `packages/agent/src/soul/generate-soul-file.ts` (or its fallback
 * template) and persisted in the `profiles.soulFile` column. Shape:
 *
 *   # <Name> — Soul File
 *
 *   ## Essence
 *   <1–3 paragraphs of identity/presence text>
 *
 *   ## Voice
 *   <voice guidance>
 *
 *   ## Style
 *   …
 *
 * The context panel has limited vertical real-estate, so we pull JUST
 * the Essence section into the panel and render it as plain text.
 * Viewing the rest of the soul happens in Settings (or future "open
 * full soul" affordance).
 *
 * Kept as a pure module so unit tests cover the extraction contract
 * without a React renderer (matches workbench convention — see
 * cited-paths.ts / tool-card-helpers.ts).
 */

const ESSENCE_HEADER_RE = /^##\s+essence\s*$/i;
const ANY_H2_RE = /^##\s+\S/;

/**
 * Extract the content of the `## Essence` section from a soul
 * markdown document. Returns the section's body text (joined
 * paragraphs, no header), OR `null` if there's no `## Essence`
 * section to render.
 *
 * - Tolerates case ("## Essence" / "## essence" / "## ESSENCE")
 * - Stops at the next `##` heading OR end of file
 * - Trims empty lines at top/bottom of the section
 * - Preserves inter-paragraph blank lines so the rendered text
 *   keeps its structure (CSS white-space: pre-line handles the
 *   visual spacing)
 */
export function extractSoulEssence(markdown: string | null | undefined): string | null {
  if (!markdown || typeof markdown !== "string") return null;
  const lines = markdown.split(/\r?\n/);

  let start = -1;
  for (let i = 0; i < lines.length; i++) {
    if (ESSENCE_HEADER_RE.test(lines[i] ?? "")) {
      start = i + 1;
      break;
    }
  }
  if (start === -1) return null;

  let end = lines.length;
  for (let j = start; j < lines.length; j++) {
    if (ANY_H2_RE.test(lines[j] ?? "")) {
      end = j;
      break;
    }
  }

  const body = lines.slice(start, end).join("\n").trim();
  return body.length > 0 ? body : null;
}

/**
 * Fallback summary for the context panel when the soul hasn't been
 * generated yet (new profile, or generation failed). Deliberately
 * phrased as a setup-invitation so users who see this in production
 * know exactly what's missing + how to fix it, rather than reading
 * lorem-ipsum-style filler.
 */
export const SOUL_FALLBACK_PROMPT =
  "Your Genie doesn't have a soul file yet. Open Settings → Profile → My Agent → Add soul instructions to give her a voice.";
